package glitch

import data.glitch_lib
import future.keywords.if

unrestricted_addresses := {"0.0.0.0", "::", "::0", "[::]"}

network_binding_attrs := {"bind", "listen", "host", "address", "ip", "interface", "endpoint", "ingress", "entrypoint", "attach", "associate", "exposed", "published", "mapped", "public", "external", "unrestricted", "open"}

service_context_keywords := {"database", "redis", "mongo", "mysql", "postgres", "cache", "message", "queue", "server", "service", "daemon", "listener", "api", "gateway", "load", "balancer", "proxy", "dashboard", "admin", "management", "console", "remote"}

# Check if a string value is an unrestricted address
is_unrestricted_address_str(str) if {
    unrestricted_addresses[str]
}

# Check if a Value node is an unrestricted address
is_unrestricted_address_value(node) if {
    node.ir_type == "String"
    is_unrestricted_address_str(node.value)
}

# Extract string from key node (handles VariableReference with :prefix, String, etc.)
key_to_string(key_node) = str if {
    key_node.ir_type == "String"
    str := key_node.value
} else if {
    key_node.ir_type == "VariableReference"
    # Handle Chef/Ruby symbols like :ip, :bind_address, 'bind-address'
    raw := key_node.value
    str := lower(trim_prefix(trim_prefix(raw, ":"), "'"))
} else if {
    key_node.ir_type == "MethodCall"
    key_node.method == "[]"
    # For access patterns, use the receiver or method name
    str := ""
} else = "" if {
    true
}

# Check if a key name suggests network binding - check both raw and cleaned versions
is_network_binding_name(name) if {
    lower_name := lower(name)
    keyword := network_binding_attrs[_]
    contains(lower_name, keyword)
}

# Generalized contains check
contains(str, substr) if {
    regex.match(sprintf(".*%s.*", [substr]), str)
}

# Check if any parent context suggests this is a service/network config
has_service_context(node) if {
    walk(node, [_, n])
    n.ir_type == "String"
    keyword := service_context_keywords[_]
    contains(lower(n.value), keyword)
}

# Recursively find unrestricted addresses in hash keys with binding names
find_unrestricted_in_hash(hash_node, parent_key_name) = result if {
    hash_node.ir_type == "Hash"
    some pair
    walk(hash_node.value, [path, pair])

    # The pair should have key and value
    key_str := key_to_string(pair.key)

    # Check if this key or parent context suggests network binding
    (is_network_binding_name(key_str); is_network_binding_name(parent_key_name))

    # Check if value is unrestricted address
    is_unrestricted_address_value(pair.value)

    result := {
        "key_name": key_str,
        "value_node": pair.value,
        "parent_name": parent_key_name
    }
}

# Recursively search any value structure for unrestricted addresses paired with binding keys
search_for_invalid_bind(root, context_name) = result if {
    root.ir_type == "Hash"
    result := find_unrestricted_in_hash(root, context_name)
} else if {
    root.ir_type == "Array"
    some elem
    walk(root.value, [_, elem])
    elem.ir_type == "Hash"
    result := find_unrestricted_in_hash(elem, context_name)
}

# Check if variable name or any nested structure contains invalid bind
check_variable_binding(var) = result if {
    # Direct value check
    is_unrestricted_address_value(var.value)
    is_network_binding_name(var.name)
    result := {
        "element": var,
        "type": "sec_invalid_bind",
        "description": "Network binding configured with unrestricted address (CWE-1327)"
    }
} else if {
    # Nested hash/array check
    found := search_for_invalid_bind(var.value, var.name)
    result := {
        "element": found.value_node,
        "type": "sec_invalid_bind",
        "description": "Network binding configured with unrestricted address (CWE-1327)"
    }
}

# Check attributes recursively
check_attribute_binding(attr) = result if {
    is_unrestricted_address_value(attr.value)
    is_network_binding_name(attr.name)
    result := {
        "element": attr,
        "type": "sec_invalid_bind", 
        "description": "Network binding configured with unrestricted address (CWE-1327)"
    }
} else if {
    found := search_for_invalid_bind(attr.value, attr.name)
    result := {
        "element": found.value_node,
        "type": "sec_invalid_bind",
        "description": "Network binding configured with unrestricted address (CWE-1327)"
    }
}

# Gather all variables from UnitBlock and nested structures
all_variables_deep(node) = vars if {
    vars := {v |
        walk(node, [_, obj])
        obj.ir_type == "Variable"
        v := obj
    }
}

# Gather all attributes deeply
all_attributes_deep(node) = attrs if {
    attrs := {a |
        walk(node, [_, obj])
        obj.ir_type == "Attribute"
        a := obj
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Search all variables deeply including in nested UnitBlocks and statements
    all_vars := all_variables_deep(parent)
    var := all_vars[_]

    check := check_variable_binding(var)

    result := {
        "type": check.type,
        "element": check.element,
        "path": parent.path,
        "description": check.description
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Search all attributes deeply
    all_attrs := all_attributes_deep(parent)
    attr := all_attrs[_]

    check := check_attribute_binding(attr)

    result := {
        "type": check.type,
        "element": check.element,
        "path": parent.path,
        "description": check.description
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Also check direct atomic unit attributes through glitch_lib
    au := glitch_lib.all_atomic_units(parent)[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

