is_unrestricted(value) {
    value == unrestricted_addresses[_]
}

is_unrestricted_addr(node) {
    node.ir_type == "String"
    is_unrestricted(node.value)
}

normalize_name(raw) = name {
    clean := regex.replace(raw, "^:+", "")
    clean2 := regex.replace(clean, "^'(.*)'$", "$1")
    name := lower(clean2)
}

has_binding_keyword(name) {
    lower_name := lower(name)
    keyword := network_binding_keywords[_]
    contains(lower_name, keyword)
}

extract_key_name(node) = name {
    node.ir_type == "String"
    name := node.value
} else = name {
    node.ir_type == "VariableReference"
    name := normalize_name(node.value)
} else = name {
    node.ir_type == "MethodCall"
    node.method == "[]"
    some idx
    node.args[idx].ir_type == "String"
    name := node.args[idx].value
} else = name {
    node.ir_type == "MethodCall"
    node.method == "[]"
    some idx
    node.args[idx].ir_type == "VariableReference"
    name := normalize_name(node.args[idx].value)
} else = "" {
    true
}

all_vars_deep(root) = vars {
    vars := {v | walk(root, [_, v]); v.ir_type == "Variable"}
}

all_attrs_deep(root) = attrs {
    attrs := {a | walk(root, [_, a]); a.ir_type == "Attribute"}
}

make_path_prefix(path, end_idx) = prefix {
    prefix := [path[j] | some j; j < end_idx; j < count(path)]
}

find_unrestricted_with_context(root, base_context) = results {
    results := {r |
        some path, node
        walk(root, [path, node])
        node.ir_type == "String"
        is_unrestricted(node.value)

        context_parts := [part |
            some i
