            part := extract_key_name(node_at_prefix)
            part != ""
        ]
        context := concat_context_parts(base_context, context_parts)
        has_binding_keyword(context)

        r := {"found": true, "element": node, "context": context}
    }
}

concat_context_parts(base, parts) = result {
    count(parts) == 0
    result := base
} else = result {
    count(parts) > 0
    joined := concat(".", parts)
    result := sprintf("%s.%s", [base, joined])
}

