walk_get(node, [head|tail]) = result {
    node.ir_type == "Hash"
    count(tail) == 0
    some pair
    walk(node.value, [_, pair])
    pair.key
    key_name := extract_key_name(pair.key)
    key_name == head
    result := pair.value
} else = result {
    node.ir_type == "Hash"
    count(tail) > 0
    some pair
    walk(node.value, [_, pair])
    pair.key
    key_name := extract_key_name(pair.key)
    key_name == head
    result := walk_get(pair.value, tail)
} else = result {
    node.ir_type == "Array"
    idx := to_number(head)
    count(tail) == 0
    result := node.value[idx]
} else = result {
    node.ir_type == "Array"
    idx := to_number(head)
    count(tail) > 0
    result := walk_get(node.value[idx], tail)
